/** 补上时间戳，得到完整题目列表 */
export const MOCK_QUESTIONS: Question[] = RAW.map((q, i) => ({
  ...q,
  createdAt: T + i * 1000,
  updatedAt: T + i * 1000,
}));

/** 按 id 取题 */
export function findQuestion(id: string): Question | undefined {
  return MOCK_QUESTIONS.find((q) => q.id === id);
}

/** 按单元取题 */
export function questionsOfUnit(unitId: string): Question[] {
  return MOCK_QUESTIONS.filter((q) => q.unitId === unitId);
}

export const MOCK_QUESTION_COUNT = MOCK_QUESTIONS.length;
